class Solution {
    public List<Integer> splitIntoFibonacci(String num) {
        long maxVal = Integer.MAX_VALUE;
        int n = num.length();
        for (int i = 1; i <= Math.min(10, n - 2); i++) {
            String s1 = num.substring(0, i);
            if (s1.length() > 1 && s1.charAt(0) == '0') break;
            long n1 = Long.parseLong(s1);
            if (n1 > maxVal) break;
            for (int j = 1; j <= Math.min(10, n - i - 1); j++) {
                String s2 = num.substring(i, i + j);
                if (s2.length() > 1 && s2.charAt(0) == '0') break;
                long n2 = Long.parseLong(s2);
                if (n2 > maxVal) break;
                List<Integer> res = new ArrayList<>();
                res.add((int) n1);
                res.add((int) n2);
                int k = i + j;
                while (k < n) {
                    long nxt = (long) res.get(res.size() - 1) + res.get(res.size() - 2);
                    if (nxt > maxVal) break;
                    String sNxt = String.valueOf(nxt);
                    if (!num.startsWith(sNxt, k)) break;
                    res.add((int) nxt);
                    k += sNxt.length();
                }
                if (k == n && res.size() >= 3) return res;
            }
        }
        return new ArrayList<>();
    }
}

var splitIntoFibonacci = function(num) {
    const MAX_VAL = 2147483647;
    const n = num.length;
    for (let i = 1; i <= Math.min(10, n - 2); i++) {
        const s1 = num.slice(0, i);
        if (s1.length > 1 && s1[0] === '0') break;
        const n1 = Number(s1);
        if (n1 > MAX_VAL) break;
        for (let j = 1; j <= Math.min(10, n - i - 1); j++) {
            const s2 = num.slice(i, i + j);
            if (s2.length > 1 && s2[0] === '0') break;
            const n2 = Number(s2);
            if (n2 > MAX_VAL) break;
            const res = [n1, n2];
            let k = i + j;
            while (k < n) {
                const nxt = res[res.length - 1] + res[res.length - 2];
                if (nxt > MAX_VAL) break;
                const sNxt = String(nxt);
                if (!num.startsWith(sNxt, k)) break;
                res.push(nxt);
                k += sNxt.length;
            }
            if (k === n && res.length >= 3) return res;
        }
    }
    return [];
